<?php
namespace App\Models\Courses;
use App\Enums\Courses\CourseEditionState;use App\Enums\Courses\CourseModality;use App\Models\User;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
class CourseEdition extends CourseModel{protected $fillable=['course_activity_id','code','state','modality','starts_on','ends_on','address','access_url','price_amount','currency','syllabus_override_json','responsible_user_id','delivery_due_days','validations_completed_at'];protected function casts():array{return ['state'=>CourseEditionState::class,'modality'=>CourseModality::class,'starts_on'=>'date','ends_on'=>'date','price_amount'=>'decimal:2','syllabus_override_json'=>'array','validations_completed_at'=>'datetime'];}public function activity():BelongsTo{return $this->belongsTo(CourseActivity::class,'course_activity_id');}public function responsible():BelongsTo{return $this->belongsTo(User::class,'responsible_user_id');}public function teachers():HasMany{return $this->hasMany(CourseEditionTeacher::class);}public function sessions():HasMany{return $this->hasMany(CourseSession::class);}public function enrollments():HasMany{return $this->hasMany(CourseEnrollment::class);}}
